#include<bits/stdc++.h>
#define elif else if
using namespace std;
const int inf=0x3f3f3f3f;
int n,m;
vector<string> s;
vector<pair<int,int>> pos[26];
int dx[4]={1,-1,0,0};
int dy[4]={0,0,1,-1};
pair<int, int> start_pos, finish_pos;
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n>>m;
    s.resize(n);
    for(int i=0;i<n;i++){
        cin>>s[i];
        for(int j=0;j<m;j++){
            if(i==0&&j==0)
                start_pos={i,j};
            elif(i==n-1&&j==m-1)
                finish_pos={i,j};
            elif('A'<=s[i][j]&&s[i][j]<='Z')
                pos[s[i][j]-'A'].push_back({i,j});
        }
    }
    vector<vector<int>> dis(n,vector<int>(m, -1));
    vector<int> vis(26,0);
    queue<pair<int,int>> q;
    dis[start_pos.first][start_pos.second] = 0;
    q.push(start_pos);
    while(!q.empty()){
        auto[x,y]=q.front();
        q.pop();
        for(int d=0;d<4;d++){
            int nx=x+dx[d],ny=y+dy[d];
            if(nx<0||nx>=n||ny<0||ny>=m)
                continue;
            if(s[nx][ny]=='1'||('A'<=s[nx][ny]&&s[nx][ny]<='Z')||dis[nx][ny]!=-1)
                continue;
            dis[nx][ny]=dis[x][y]+1;
            q.push({nx,ny});
        }
        if('A'<=s[x][y]&&s[x][y]<='Z'){
            int c=s[x][y]-'A';
            if(!vis[c]){
                vis[c]=1;
                for(auto [nx,ny]:pos[c]){
                    if(dis[nx][ny]!=-1)
                        continue;
                    dis[nx][ny]=dis[x][y]+1;
                    q.push({nx,ny});
                }
            }
        }
    }
    int ans=dis[finish_pos.first][finish_pos.second];
    if (ans==-1)
        cout<<"No Solution.";
    else
        cout<<ans-1;
    return 0;
}
